import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"鼎","description":"东坡易传 - 鼎","frontmatter":{"title":"鼎","description":"东坡易传 - 鼎"},"headers":[],"relativePath":"zh/classics/dongpo/051.md","filePath":"zh/classics/dongpo/051.md"}'),o={name:"zh/classics/dongpo/051.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="鼎" tabindex="-1">鼎 <a class="header-anchor" href="#鼎" aria-label="Permalink to “鼎”">​</a></h1><p>“鼎”：元吉，亨。</p><p>《彖》曰：“鼎”，象也。以木“巽”火，亨飪也。聖人亨以享上帝，而大亨以養聖賢。 “巽”而耳目聰明，柔進而上行，得中而應乎剛，是以“元亨”。</p><p>“象”者，可見之謂也。天之生物不可見，既生而剛強之者可見也。聖人之創業，其所以創之者不可見，其成就熟好，使之堅凝而不壞者可見也。故象曰“君子以正位凝命。”“革”所以改命，而“鼎”所以凝之也；知“革”而不知“鼎”，則上下之分不明而位不正，雖其所受於天者，流泛而不可知矣。大器非器也，大亨非亨也。取“鼎”之用而施之天下，謂之“大亨”。“鼎”之用，極於亨帝而已，以其道養聖賢，則亨之大者也。國有聖賢，則君位定而天命固矣。 “元亨”，所謂“元吉，亨”也。柔進而上行者，五也；五得中而應乎剛，則所以爲耳目者，“巽”也。</p><p>象曰：木上有火，“鼎”；君子以正位凝命。</p><p>初六：鼎顛趾，利出否；得妾以其子，無咎。象曰：“鼎顛趾”，未悖也；“利出否”，以從貴也。</p><p>六爻皆“鼎”也。當其處者有其象，故以初爲“趾”，二與三四爲“腹”而實在焉；五與上爲“耳”。初六上應九四，顛趾之象也；夫“鼎”，聖人將“以正位凝命”，亨而熟之至於可食而後已；苟有不善者在焉，則善與不善皆亨而並熟，而善者棄矣。鼎於是，未有實也；故及其未有實而顛之，以同其不善。如待其有實，則夫不善已污之矣，實非吾之所欲棄也。於是焉而顛之以其所欲棄，出其所不欲棄，則天下之亂或自是起矣。故曰：“鼎顛趾，未悖也。”“顛趾”而“出否”，盡去之道也；盡去之，則患鼎無實。聖人之於人也，責其身不問其所從，論其今不考其素，苟騂且角，犁牛之子可也。鼎雖以“出否”爲利，而擇之太詳、求之太備，天下無完人。故曰：“得妾以其子，無咎。”從其子之爲貴，則其出於妾者可忘也。</p><p>九二：鼎有實，我仇有疾，不我能即，吉。象曰：“鼎有實”，慎所之也；“我仇有疾”，終無尤也。</p><p>九二始有“實”者，“仇”者六五也。所謂“耳”也，九二之實，六五之所舉也。故其象曰“鼎黃耳”。中以爲實也，“仇有疾”而不能即我，畏九四也。“鼎”以耳行，故耳能即之則食，不能即之，則不食之道也。始有實者以不食爲吉，惡其未足而輕用之也。故曰：“鼎有實，慎所之也。”</p><p>九三：鼎耳革，其行塞。雉膏不食，方雨虧悔，終吉。象曰：“鼎耳革”，失其義也。</p><p>“耳”，上九也。九三之實，上九之所舉也。熟物之謂革，鼎之熟物，以腹不以耳；而上九“離”之極，火之所炎，以耳革者也。耳之受炎也，足以廢塞其行而不足以革，故曰：“鼎耳革，失其義也。”九三，實之將盈者也，於是可食矣，而其行廢，故雖有“雉膏”而不食也。耳以兩舉者也，六五之耳可“鉉”，而上九之耳不可鉉，則六五雖欲獨舉得乎？陰欲行而陽欲留，其爲悔也大矣，故至於雨然後悔，虧而終吉。雨者，陰陽之和，“玉鉉”之功也。</p><p>九四：鼎折足，覆公餗，其形渥，兇。象曰：“覆公餗”，信如何也？</p><p>鼎之量，極於四，其上則耳矣。受實必有餘量，以爲溢地也。故九三以不食爲憂，明不可復加也；至於九四，溢則覆矣。故孔子曰：“德薄而位尊，知小而謀大，力少而任重，鮮不及矣。”方其未及也，必有告之者而不信，及其已信，則無如之何矣。</p><p>六五：鼎黃耳，金鉉；利貞。象曰：“鼎黃耳”，中以爲實也。</p><p>上九：鼎玉鉉，大吉；無不利。象曰：“玉鉉”在上，剛柔節也。</p><p>六五、上九，皆所謂“耳”也。上九之耳，見於九三，故不復出也；在炎而不灼者，玉也；金則廢矣。六五之爲耳也，中而不亢，柔而有容，故曰“黃耳”，則其所以爲“鉉”者，以金足矣。上九之爲耳也，炎而灼，不可以迫，故曰“耳革”，則其所以爲鉉者，玉而後可。金鉉可以及五而不可以及上，玉鉉則可以兩及矣。可以兩及，則上九之剛、六五之柔，我爲之節也。九二之實，利在於不食，故六五之耳，利在於貞而不行；九三之實，以不食爲憂，故上九之耳，得玉鉉則“大吉，無不利”。無不利者，上與五、與三之所利也。以鼎熟物，人皆能之；至於鼎盈而憂溢、耳炎而不可舉，非玉鉉不能。此“鼎”之所以“養聖賢”也。</p>',16)])])}const m=a(o,[["render",r]]);export{h as __pageData,m as default};
